class CRMLead {
    setup() {
        if (!this._originalDocumentContext.fieldPropertyOverrides) {
            this._originalDocumentContext.fieldPropertyOverrides = {};
        }
        this._originalDocumentContext.fieldPropertyOverrides['chat_summary'] = {
            fieldtype: 'HTML',
            options: '<div class="text-sm text-ink-gray-9 leading-relaxed">{{ chat_summary }}</div>'
        };
        this.updateConversationLink();
    }

    refresh() {
        this.updateConversationLink();
    }

    updateConversationLink() {
        const conv = this.doc?.custom_conversation;
        if (conv && typeof conv === 'string' && conv.trim()) {
            const trimmed = conv.trim();
            const url = `/desk/chatbot-conversation/${trimmed}`;
            const html = `<a href="${url}" class="text-sm text-blue-600 hover:text-blue-800 underline font-medium inline-flex items-center gap-1" style="color: #2563eb; text-decoration: underline;">Open Conversation ↗</a>`;
            this.setFieldProperty('custom_conversation', 'fieldtype', 'HTML');
            this.setFieldProperty('custom_conversation', 'options', html);
            this.setFieldHtml('custom_conversation', html);
        } else {
            this.setFieldProperty('custom_conversation', 'fieldtype', 'HTML');
            this.setFieldProperty('custom_conversation', 'options', '');
            this.setFieldHtml('custom_conversation', '');
        }
    }
}
